import { ExecArgs } from "@medusajs/framework/types"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"

/**
 * Generated by Medusa Cloud. Replaces the S3 file URLs stored in the database
 * with their CDN equivalents, so existing files are served through the CDN.
 */
const FILE_URL_MAPPINGS = [
  {
    "from": "https://s3.us-east-1.amazonaws.com/medusajs.cloud-data-staging-use1-20241105160614260300000001/",
    "to": "https://files.us-east-1.medusajs-staging.app/medusajs.cloud-data-staging-use1-20241105160614260300000001/"
  }
]

const FILE_URL_COLUMNS = [
  {
    "table": "image",
    "column": "url"
  },
  {
    "table": "product",
    "column": "thumbnail"
  },
  {
    "table": "product_variant",
    "column": "thumbnail"
  },
  {
    "table": "inventory_item",
    "column": "thumbnail"
  },
  {
    "table": "cart_line_item",
    "column": "thumbnail"
  },
  {
    "table": "order_line_item",
    "column": "thumbnail"
  },
  {
    "table": "order_claim_item_image",
    "column": "url"
  },
  {
    "table": "user",
    "column": "avatar_url"
  },
  {
    "table": "fulfillment_label",
    "column": "label_url"
  }
]

export default async function migrateFileUrlsToCdn({ container }: ExecArgs) {
  const logger = container.resolve(ContainerRegistrationKeys.LOGGER)
  const pgConnection = container.resolve(
    ContainerRegistrationKeys.PG_CONNECTION
  )

  await pgConnection.transaction(async (trx) => {
    for (const { table, column } of FILE_URL_COLUMNS) {
      const { rows } = await trx.raw("SELECT to_regclass(?) AS name", [table])
      if (!rows[0]?.name) {
        continue
      }

      for (const { from, to } of FILE_URL_MAPPINGS) {
        const result = await trx.raw(
          "UPDATE ?? SET ?? = ? || substr(??, ?) WHERE left(??, ?) = ?",
          [table, column, to, column, from.length + 1, column, from.length, from]
        )

        if (result.rowCount) {
          logger.info(
            `Moved ${result.rowCount} ${table}.${column} file URL(s) to the CDN`
          )
        }
      }
    }
  })
}
